  g045:["restriction"],g046:["method","tradition"],g047:["troublesome"],g048:["decide"],g049:["speed up"],g050:["aged","old"],
  g051:["helpful","advantageous","wholesome"],g052:["lasting"],g053:["aware","knowing"],g054:["reduce","lessen"],g055:["resistance"],
